def parse_hhmm(s):
    if len(s) != 5 or s[2] != ':':
        raise ValueError('expected HH:MM')
    hh = s[0:2]
    mm = s[3:5]
    if not (hh.isdigit() and mm.isdigit()):
        raise ValueError('non-digit field')
    hours = int(hh)
    minutes = int(mm)
    if not (0 <= hours <= 23):
        raise ValueError('hour out of range')
    if not (0 <= minutes <= 59):
        raise ValueError('minute out of range')
    return hours * 60 + minutes
